html:
{#- Tanda terima barang dari supplier, dicetak dari Purchase Receipt -#}
{#- nomor PO ngikut centangan Print Original Number di PO-nya masing-masing -#}
{%- set purchase_orders = get_print_names("Purchase Order", doc.items | map(attribute="purchase_order") | select | unique | list) -%}

<style>
	.vic-pf .po { margin-top: 12px; }
	.vic-pf .po .lbl { display: inline-block; width: 62px; }
	.vic-pf .items th { border-bottom: 1px dotted #444; }
	.vic-pf .items td { border-bottom: 1px dotted #444; padding: 10px 4px !important; }
	.vic-pf .serials { text-align: center; font-size: 9px; word-break: break-all; }
	.vic-pf .remarks { margin-top: 14px; font-size: 10px; }
	.vic-pf .sign { margin-top: 44px; }
	.vic-pf .sign td { width: 33%; padding: 0 10px !important; }
	.vic-pf .sign .space { height: 62px; border-bottom: 1px solid #000; }
	.vic-pf .sign .role { padding-top: 5px !important; padding-bottom: 0 !important; }
</style>

<div class="vic-pf">
	{%- include "vic_addon/templates/print_formats/vic_letterhead.html" -%}

	<div class="title-wrap">
		<div class="title-block">
			<div class="doc-title">GOODS RECEIVED</div>
			<table class="meta">
				<tr>
					<td class="lbl">GR No.</td>
					<td class="sep">:</td>
					<td>{{ get_print_name(doc) }}</td>
				</tr>
				<tr>
					<td class="lbl">Date</td>
					<td class="sep">:</td>
					<td>{{ frappe.utils.formatdate(doc.posting_date, "MMMM d, yyyy") }}</td>
				</tr>
			</table>
		</div>
	</div>

	<div class="po">
		<span class="lbl">PO No.</span>: {{ purchase_orders | join(", ") if purchase_orders else "-" }}
	</div>

	<table class="items">
		<thead>
			<tr>
				<th style="width: 8%">Item</th>
				<th style="width: 20%">Heat Number</th>
				<th class="left" style="width: 50%">Description</th>
				<th style="width: 22%">Qty</th>
			</tr>
		</thead>
		<tbody>
			{%- set ns = namespace(no = 0) %}
			{%- for header, rows in group_items_by_header(doc.items) %}
				{%- if header %}
					{#- judul kelompok mulai di kolom Description, kolom sebelumnya dikosongin -#}
					<tr class="group pengiriman"><td></td><td></td><td class="text" colspan="2">{{ header }}</td></tr>
				{%- endif %}
				{%- for item in rows %}
					{%- set ns.no = ns.no + 1 %}
					{%- set size = frappe.db.get_value("Item", item.item_code, "custom_size") %}
					<tr>
						<td class="num">{{ ns.no }}</td>
						{#- Heat Number = serial number barangnya #}
						<td class="serials">
							{%- for serial_no in get_row_serial_nos(item) %}<div>{{ serial_no }}</div>{% else %}-{% endfor %}
						</td>
						<td class="text">
							<div class="desc">{{ get_item_description(item) }}</div>
							{%- if size %}<div>Size : {{ size }}</div>{% endif %}
						</td>
						<td class="qty">{{ "%.2f" | format(item.qty | float) }} {{ item.uom }}</td>
					</tr>
				{%- endfor %}
			{%- endfor %}
		</tbody>
	</table>

	{%- if doc.remarks and doc.remarks != "No Remarks" %}
		<div class="remarks"><b>Remarks:</b> {{ doc.remarks }}</div>
	{%- endif %}

	<table class="sign">
		<tr>
			<td class="space"></td>
			<td class="space"></td>
			<td class="space"></td>
		</tr>
		<tr>
			<td class="role">Received By</td>
			<td class="role">Checked By</td>
			<td class="role">Approved By</td>
		</tr>
	</table>
	{%- include "vic_addon/templates/print_formats/vic_footer.html" -%}
</div>
